krpano.action:
if(caller.linkedscene,
	copy(hs_linkedscene, caller.linkedscene);
	if(caller.linkedscene_lookat, txtsplit(caller.linkedscene_lookat, ',', hs_lookat_h, hs_lookat_v, hs_lookat_fov); );
	set(caller.enabled, false);
	skin_hidetooltips();
	hide_custom_tooltip();

	tween(caller.oy|caller.alpha|caller.rx, -50|0.0|90, 0.5, easeOutQuad,
		skin_loadscene(get(hs_linkedscene), get(skin_settings.loadscene_blend));
		if(hs_lookat_h !== null, skin_lookat(get(hs_lookat_h), get(hs_lookat_v), get(hs_lookat_fov)); );
		skin_updatescroll();
	);
);

if(hotspot[%1].loaded,
	inc(hotspot[%1].myframe);
	if(hotspot[%1].myframe GT 23, set(hotspot[%1].myframe, 0));
	mul(hs_cx, hotspot[%1].myframe, 120);
	txtadd(hotspot[%1].crop, get(hs_cx), '|0|120|250');

	tween(hotspot[%1].myframe_timer, 1.0, 0.03, linear, hotspot_sprite_anim(%1) );
);

if(caller.linkedscene,
	copy(hs_linkedscene, caller.linkedscene);
	if(caller.linkedscene_lookat, txtsplit(caller.linkedscene_lookat, ',', hs_lookat_h, hs_lookat_v, hs_lookat_fov); );
	set(caller.enabled, false);
	skin_hidetooltips();
	hide_custom_tooltip();
	tween(caller.depth|caller.alpha|caller.oy, 4000|0.0|-50, 0.5, default,
		skin_loadscene(get(hs_linkedscene), ZOOMBLEND(2.0, 2.0, easeInOutSine));
		if(hs_lookat_h !== null, skin_lookat(get(hs_lookat_h), get(hs_lookat_v), get(hs_lookat_fov)); );
		skin_updatescroll();
	);
);


set(can_show_title, true);
set(can_show_thumb, true);

if(show_title === 'false' OR show_title === false, set(can_show_title, false) );
if(show_thumb === 'false' OR show_thumb === false, set(can_show_thumb, false) );

set(tooltip_txt, '');
set(tooltip_thumb, '');

if(can_show_title,
	if(linkedscene,
		if(custom_title === null OR custom_title === '' OR custom_title === 'Mũi tên di chuyển mới' OR custom_title === 'Ghim vị trí mới',
			copy(tooltip_txt, scene[get(linkedscene)].title);
		,
			copy(tooltip_txt, custom_title);
		);
	,
		copy(tooltip_txt, custom_title);
	);
);

if(can_show_thumb,
	if(linkedscene,
		if(custom_thumb === null OR custom_thumb === '',
			copy(tooltip_thumb, scene[get(linkedscene)].thumburl);
		,
			copy(tooltip_thumb, custom_thumb);
		);
	,
		copy(tooltip_thumb, custom_thumb);
	);
);


if(tooltip_txt OR tooltip_thumb,
	set(layer[custom_tooltip].visible, true);


	if(tooltip_txt AND tooltip_thumb,
		set(layer[custom_tooltip_text].html, get(tooltip_txt));
		set(layer[custom_tooltip_text].visible, true);
		set(layer[custom_tooltip_text].y, 105);

		set(layer[custom_tooltip_thumb].url, get(tooltip_thumb));
		set(layer[custom_tooltip_thumb].visible, true);

		set(layer[custom_tooltip].width, 180);
		set(layer[custom_tooltip].height, 138);
	);


	if(!tooltip_txt AND tooltip_thumb,
		set(layer[custom_tooltip_text].visible, false);

		set(layer[custom_tooltip_thumb].url, get(tooltip_thumb));
		set(layer[custom_tooltip_thumb].visible, true);

		set(layer[custom_tooltip].width, 180);
		set(layer[custom_tooltip].height, 107);
	);


	if(tooltip_txt AND !tooltip_thumb,
		set(layer[custom_tooltip_text].html, get(tooltip_txt));
		set(layer[custom_tooltip_text].visible, true);
		set(layer[custom_tooltip_text].y, 5);

		set(layer[custom_tooltip_thumb].visible, false);

		set(layer[custom_tooltip].width, 180);
		set(layer[custom_tooltip].height, 36);
	);


	asyncloop(layer[custom_tooltip].visible,
		set(layer[custom_tooltip].x, get(mouse.x));
		calc(layer[custom_tooltip].y, mouse.y - 45);
	);

	tween(layer[custom_tooltip].alpha, 1.0, 0.15);
);

if(webvr.isenabled,
	set(vr_gaze.gazing, true);
	copy(vr_gaze.target_scene, caller.linkedscene);
	tween(caller.scale, 0.50, 0.25, easeOutQuad);
	tween(caller.alpha, 1.0, 0.2);
	set(layer[vr_gaze_bar].visible, true);
	set(layer[vr_gaze_track].visible, true);
	set(layer[vr_gaze_bar].width, 0);
	tween(layer[vr_gaze_track].alpha, 1.0, 0.2);
	tween(layer[vr_gaze_bar].alpha, 1.0, 0.2);
	tween(layer[vr_gaze_bar].width, 160, 1.8, linear, vr_gaze_confirm());
);

set(vr_gaze.gazing, false);
tween(caller.scale, 0.38, 0.2);
tween(caller.alpha, 0.85, 0.2);
set(layer[vr_gaze_bar].width, 0);
tween(layer[vr_gaze_track].alpha, 0.0, 0.25, default, set(layer[vr_gaze_track].visible, false));
tween(layer[vr_gaze_bar].alpha, 0.0, 0.25, default, set(layer[vr_gaze_bar].visible, false));

if(vr_gaze.gazing,
	set(vr_gaze.gazing, false);
	tween(layer[vr_gaze_track].alpha, 0.0, 0.2, default, set(layer[vr_gaze_track].visible, false));
	tween(layer[vr_gaze_bar].alpha, 0.0, 0.2, default, set(layer[vr_gaze_bar].visible, false));
	skin_loadscene(get(vr_gaze.target_scene), ZOOMBLEND(2.0, 2.0, easeInOutSine));
);

if(startscene === null OR !scene[get(startscene)], copy(startscene, scene[0].name); );
if(scene[get(startscene)],
	loadscene(get(startscene), null, MERGE);
);
if(startactions !== null, startactions() );
